import {
  NORMAL_SEND_INTERVAL_SECONDS,
  SEND_PROCESSING_ALLOWANCE_SECONDS,
} from "@/lib/email-limits";

// The denominator covers the whole batch, rather than restarting for each send.
export function batchCountdownProgress(
  startAt: number,
  endAt: number,
  now: number,
) {
  const duration = endAt - startAt;
  return duration > 0 ? Math.max(0, Math.min(1, (endAt - now) / duration)) : 0;
}

export function estimateSeconds(
  outstanding: number,
  nextSendAt: string | null = null,
  now = 0,
) {
  if (!outstanding) return 0;
  const parsed = nextSendAt ? Date.parse(nextSendAt) : now;
  const wait = Number.isFinite(parsed) ? Math.max(0, (parsed - now) / 1000) : 0;
  return Math.ceil(
    wait +
      Math.max(0, outstanding - 1) * NORMAL_SEND_INTERVAL_SECONDS +
      outstanding * SEND_PROCESSING_ALLOWANCE_SECONDS,
  );
}

export function remainingRange(
  outstanding: number,
  nextSendAt: string | null,
  now: number,
) {
  if (!outstanding) return null;
  const seconds = estimateSeconds(outstanding, nextSendAt, now);
  return {
    min: Math.max(1, Math.floor(seconds / 60)),
    max: Math.max(1, Math.ceil(seconds / 60)),
  };
}
